export function containsOutboundSecret(text: string): boolean {
  return detectSecrets(text).length > 0 || detectEntropy(text).length > 0;
}

function isAllowShapedValue(value: string): boolean {
  return (
    FULL_GIT_SHA_RE.test(value) ||
    SHORT_GIT_SHA_RE.test(value) ||
    UUID_RE.test(value) ||
    INTEGRITY_RE.test(value)
  );
}
